const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometries for central Oklahoma and northern Texas
  const centralOklahoma = ee.Geometry.Rectangle([-98.5, 34.5, -96.5, 36.5]); // Approximate central OK
  const northernTexas = ee.Geometry.Rectangle([-101.0, 32.0, -98.0, 34.0]); // Approximate northern TX

  // 2. Time period
  const startDate = '2007-08-10';
  const endDate = '2007-08-20';

  // 3. Load TRMM daily precipitation data
  const trmmCol = ee.ImageCollection('TRMM/3B42RT/Daily')
    .filterDate(startDate, endDate)
    .select('precipitation');

  // 4. Check if collection has data
  const colSize = trmmCol.size().getInfo();
  console.log(`TRMM Images (2007-08-10 to 2007-08-20): ${colSize}`);

  if (colSize === 0) {
    console.log("No TRMM data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Create a composite (sum of precipitation over the period)
  const precipSum = trmmCol.sum();

  // 6. Calculate mean precipitation for each region
  const reduceConfig = {
    reducer: ee.Reducer.mean(),
    geometry: null,
    scale: 10000,
    maxPixels: 1e9
  };

  // Central Oklahoma
  reduceConfig.geometry = centralOklahoma;
  const okPrecip = precipSum.reduceRegion(reduceConfig).get('precipitation');
  const okVal = okPrecip.getInfo();

  // Northern Texas  
  reduceConfig.geometry = northernTexas;
  const txPrecip = precipSum.reduceRegion(reduceConfig).get('precipitation');
  const txVal = txPrecip.getInfo();

  console.log(`Central OK total precipitation (mm): ${okVal !== null ? okVal.toFixed(2) : 'null'}`);
  console.log(`Northern TX total precipitation (mm): ${txVal !== null ? txVal.toFixed(2) : 'null'}`);

  // 7. Check for valid results
  if (okVal === null || txVal === null || 
      isNaN(okVal) || isNaN(txVal) ||
      okVal < 0 || txVal < 0) { // Negative precipitation is invalid
    console.log("Invalid precipitation values calculated.");
    console.log("<answer>C3</answer>");
    return;
  }

  // 8. Compare and output answer
  if (okVal > txVal) {
    console.log("Central Oklahoma has higher precipitation.");
    console.log("<answer>A</answer>");
  } else {
    console.log("Northern Texas has equal or higher precipitation.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
